import { OpenRouterError } from '../utils/errors';

const ENDPOINT = 'https://openrouter.ai/api/v1/chat/completions';
const MODEL = process.env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct';

/**
 * Calls OpenRouter with structured prompt for support ticket investigation.
 * Returns parsed JSON object generated by the model.
 */
export async function callOpenRouter(payload: any): Promise<any> {
  const apiKey = process.env.OPENROUTER_API_KEY;
  if (!apiKey || apiKey === 'your_openrouter_api_key_here') {
    throw new OpenRouterError('OpenRouter API key is missing or not configured. Please set OPENROUTER_API_KEY in backend/.env', 401);
  }

  const promptContent = `You are an expert autonomous AI Customer Support Agent for an Indian retail/e-commerce platform.
Analyze this customer support ticket:

Subject: ${payload.subject || 'N/A'}
Customer: ${payload.customer?.name || 'Customer'} (${payload.customer?.company || payload.customer?.region || 'India'})
Priority: ${payload.priority || 'medium'}
Category: ${payload.category || 'Billing & Checkout'}
Messages:
${(payload.messages || []).map((m: any) => `- [${m.senderType} - ${m.senderName}]: ${m.content}`).join('\n')}

Return a valid, single JSON object (with NO markdown formatting, NO backticks) following this schema:
{
  "issueSummary": "Clear 1-2 sentence summary of the issue in Indian context (INR ₹)",
  "rootCauseAnalysis": "Technical and operational investigation of why this issue occurred (e.g. gateway callback timeout, duplicate charge, warehouse packing mixup, courier rain delay, promo session refresh drop)",
  "category": "Billing & Checkout",
  "priority": "urgent",
  "confidenceScore": 96,
  "sentiment": {
    "level": "urgent",
    "score": 88,
    "summary": "Customer sentiment analysis",
    "drivers": ["Key distress driver 1", "Key distress driver 2"]
  },
  "extractedEntities": [
    { "label": "Order Number", "value": "ORD-...", "type": "system" },
    { "label": "Amount", "value": "₹...", "type": "billing" }
  ],
  "investigationLogs": [
    {
      "id": "log-1",
      "source": "Billing Ledger",
      "status": "error",
      "timestamp": "08:14 UTC",
      "title": "Log title",
      "details": "Factual details of transaction or shipment"
    }
  ],
  "matchedKnowledge": [
    {
      "id": "kb-1",
      "title": "SOP or Runbook title",
      "category": "Policy Category",
      "relevanceScore": 98,
      "snippet": "Relevant procedure rule snippet",
      "source": "Internal Runbook"
    }
  ],
  "suggestedActions": [
    {
      "id": "act-1",
      "title": "Action title (e.g. Initiate Refund of ₹1,499)",
      "description": "What this action accomplishes",
      "type": "refund",
      "impact": "low"
    }
  ],
  "draftCustomerReply": {
    "greeting": "Hi ${payload.customer?.name ? payload.customer.name.split(' ')[0] : 'there'},",
    "tone": "Empathetic & Technical",
    "body": "Comprehensive, courteous response directly addressing the customer with realistic INR (₹) amounts, timelines, and reference IDs.",
    "keyPointsCovered": [
      "Key point 1",
      "Key point 2"
    ]
  }
}`;

  const requestBody = {
    model: MODEL,
    temperature: 0.1,
    response_format: { type: 'json_object' },
    messages: [
      {
        role: 'system',
        content: 'You are an AI Support Ticket Analysis engine. You must return ONLY raw JSON matching the requested schema. No code fences, no explanations.'
      },
      {
        role: 'user',
        content: promptContent
      }
    ]
  };

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 25000); // 25s timeout

  try {
    const res = await fetch(ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
        'HTTP-Referer': 'https://github.com/hackathon/support-ai-management-agent'
      },
      body: JSON.stringify(requestBody),
      signal: controller.signal
    });

    if (!res.ok) {
      const txt = await res.text();
      let parsedErr = txt;
      try {
        const jsonErr = JSON.parse(txt);
        parsedErr = jsonErr.error?.message || txt;
      } catch {}
      throw new OpenRouterError(`OpenRouter API error (${res.status}): ${parsedErr}`, res.status);
    }

    const json = await res.json();
    const content = json.choices?.[0]?.message?.content;
    if (!content) {
      throw new OpenRouterError('No content returned from OpenRouter', 500);
    }

    let cleaned = content.trim();
    if (cleaned.startsWith('```json')) {
      cleaned = cleaned.replace(/^```json\s*/, '').replace(/```\s*$/, '');
    } else if (cleaned.startsWith('```')) {
      cleaned = cleaned.replace(/^```\s*/, '').replace(/```\s*$/, '');
    }

    return JSON.parse(cleaned);
  } catch (e: any) {
    if (e.name === 'AbortError') {
      throw new OpenRouterError('OpenRouter request timed out after 25s', 504);
    }
    if (e instanceof OpenRouterError) throw e;
    throw new OpenRouterError(e.message || 'Unknown OpenRouter error', 500);
  } finally {
    clearTimeout(timeout);
  }
}
